<?php
if(!isset($db,$guru_id,$pengajaran_list)){http_response_code(404);exit;}
$uhPid=(int)($_GET['rekap_pengajaran']??($pengajaran_list[0]['id']??0));$uhAssignment=null;
foreach($pengajaran_list as $a)if((int)$a['id']===$uhPid)$uhAssignment=$a;
$uhExams=[];$uhRows=[];$uhGrades=[];$uhSessions=[];
if($uhAssignment){
    $regular=uh_regular_sql($db);$q=$db->prepare("SELECT * FROM ujian u WHERE pengajaran_id=? AND jenis_ujian='Kuis' AND $regular ORDER BY id");$q->execute([$uhPid]);$uhExams=$q->fetchAll();
    $q=$db->prepare('SELECT id,nisn,nama_lengkap FROM siswa WHERE kelas_id=? ORDER BY nama_lengkap');$q->execute([$uhAssignment['kelas_id']]);$uhRows=$q->fetchAll();
    $q=$db->prepare('SELECT n.* FROM nilai_ujian n JOIN ujian u ON u.id=n.ujian_id WHERE u.pengajaran_id=?');$q->execute([$uhPid]);foreach($q->fetchAll() as $n)$uhGrades[$n['siswa_id']][$n['ujian_id']]=$n['nilai_total'];
    $q=$db->prepare('SELECT se.* FROM sesi_ujian se JOIN ujian u ON u.id=se.ujian_id WHERE u.pengajaran_id=?');$q->execute([$uhPid]);foreach($q->fetchAll() as $n)$uhSessions[$n['siswa_id']][$n['ujian_id']]=$n['status'];
}
?>
<section id="rekap-ujian" class="card border-0 shadow-sm p-3 p-md-4 mt-4 uh-recap">
<div class="d-flex flex-wrap justify-content-between gap-2 mb-3"><div><h2 class="h6 fw-bold">Rekap Ulangan Harian</h2><p class="small text-muted mb-0">Nilai setiap UH dan rata-rata siswa. Nilai final masuk otomatis ke Rekap Nilai.</p></div><?php if($uhAssignment): ?><div class="uh-recap-actions"><?php if($uhExams): ?><a class="btn btn-sm btn-outline-secondary" href="ujian_nilai.php?pengajaran_id=<?= $uhPid ?>&amp;ujian_id=<?= (int)$uhExams[0]['id'] ?>&amp;panel=impor"><i class="fa-solid fa-file-import me-1" aria-hidden="true"></i>Impor nilai</a><a class="btn btn-sm btn-outline-secondary" href="ujian_nilai.php?pengajaran_id=<?= $uhPid ?>&amp;ujian_id=<?= (int)$uhExams[0]['id'] ?>&amp;panel=remedial"><i class="fa-solid fa-clock-rotate-left me-1" aria-hidden="true"></i>Remedial / Undo</a><?php endif ?><a class="btn btn-sm btn-outline-primary" href="rekap_nilai_guru.php?pengajaran_id=<?= $uhPid ?>">Buka Rekap Nilai</a></div><?php endif ?></div>
<form method="get" action="#rekap-ujian" class="mb-3 uh-recap-filter"><label for="uhRekapPengajaran" class="form-label">Mata pelajaran dan kelas</label><div class="d-flex flex-wrap gap-2"><select id="uhRekapPengajaran" name="rekap_pengajaran" class="form-select" style="max-width:650px" onchange="this.form.submit()"><?php foreach($pengajaran_list as $a): ?><option value="<?= (int)$a['id'] ?>" <?= (int)$a['id']===$uhPid?'selected':'' ?>><?= sanitize($a['nama_mapel'].' - '.$a['nama_kelas'].' ('.($a['semester']??'').' '.($a['tahun_ajaran']??'').')') ?></option><?php endforeach ?></select><button class="btn btn-outline-primary">Tampilkan</button></div></form>
<?php if(!$uhExams): ?><p class="text-muted text-center py-4">Belum ada ulangan harian pada pengajaran ini.</p><?php else: ?>
<div class="table-responsive" tabindex="0" role="region" aria-label="Rekap seluruh ulangan harian"><table class="table align-middle uh-recap-table"><thead class="table-light"><tr><th>Siswa</th><?php foreach($uhExams as $exam):$settings=uh_settings($db,(int)$exam['id'],$uhPid); ?><th style="min-width:155px"><a href="ujian_hasil.php?ujian_id=<?= (int)$exam['id'] ?>">UH <?= (int)$settings['nomor'] ?></a><small class="d-block fw-normal"><?= sanitize($exam['nama_ujian']) ?></small></th><?php endforeach ?><th>Rata-rata</th></tr></thead><tbody>
<?php foreach($uhRows as $student): ?><tr><th scope="row"><?= sanitize($student['nama_lengkap']) ?><small class="d-block text-muted fw-normal"><?= sanitize($student['nisn']) ?></small></th>
<?php foreach($uhExams as $exam):$eid=(int)$exam['id'];$sid=(int)$student['id'];$eligible=uh_ready($db)?uh_eligible_sql('u.id',(string)$sid):'1=1';$pending=uh_pending_sql('u.id',(string)$sid);$q=$db->prepare("SELECT $eligible eligible,$pending pending,(u.waktu_selesai<=NOW()) expired FROM ujian u WHERE u.id=?");$q->execute([$eid]);$flags=$q->fetch();$grade=$uhGrades[$sid][$eid]??null;$status=$uhSessions[$sid][$eid]??null; ?><td><?php if(!$flags['eligible']): ?><span class="text-muted">Bukan penerima</span><?php elseif($flags['pending']||($status==='Selesai'&&$grade===null)): ?><span class="badge bg-warning text-dark">Menunggu penilaian</span><?php elseif($grade!==null): ?><strong><?= number_format((float)$grade,2) ?></strong><?php elseif($status==='Berlangsung'): ?><span class="text-primary">Sedang mengerjakan</span><?php elseif($flags['expired']): ?><span class="text-danger">0 <small>Belum mengerjakan</small></span><?php else: ?><span class="text-muted">Belum mengerjakan</span><?php endif ?></td><?php endforeach ?>
<?php $avg=uh_average_sql($db,'?','?');$q=$db->prepare('SELECT '.$avg);$q->execute([$student['id'],$uhPid]); ?><td><strong><?= number_format((float)$q->fetchColumn(),2) ?></strong></td></tr><?php endforeach ?>
</tbody></table></div><?php endif ?></section>
